package cn.zhuatech.finagent.service;import jakarta.validation.constraints.*;import org.springframework.stereotype.Service;import java.util.*;
@Service public class JournalProposalReleaseService{public Assessment assess(Request r){List<String>b=new ArrayList<>(),a=new ArrayList<>();if(!r.supportingEvidenceComplete())b.add("记账建议缺少完整支持凭证");if(!r.accountingPeriodOpen())b.add("目标会计期间未开放");if(!r.debitsAndCreditsBalanced())b.add("借贷不平");if(!r.accountsAndEntityValidated())b.add("科目或核算主体未验证");if(!r.segregationOfDutiesMet())b.add("生成、审批和入账职责未分离");if(!r.taxTreatmentReviewed())b.add("税务处理未复核");if(r.duplicateRiskDetected())b.add("检测到重复入账风险");if(r.materialAdjustment()&&!r.materialApprovalComplete())b.add("重大调整未获专项批准");if(!r.finalApprovalComplete())b.add("凭证发布审批未完成");if(!b.isEmpty()){a.add("阻断凭证入账并完成财务控制复核");return new Assessment(Decision.BLOCKED,b,a);}if(!r.auditTrailComplete()||!r.reversalPlanReady()){if(!r.auditTrailComplete())a.add("补齐建议来源、人工修改和审批审计");if(!r.reversalPlanReady())a.add("准备冲销凭证和错误恢复方案");return new Assessment(Decision.REVIEW,b,a);}a.add("批准凭证入账并归档证据、版本和审批记录");return new Assessment(Decision.POST,b,a);}public record Request(@NotBlank String proposalId,boolean supportingEvidenceComplete,boolean accountingPeriodOpen,boolean debitsAndCreditsBalanced,boolean accountsAndEntityValidated,boolean segregationOfDutiesMet,boolean taxTreatmentReviewed,boolean duplicateRiskDetected,boolean materialAdjustment,boolean materialApprovalComplete,boolean auditTrailComplete,boolean reversalPlanReady,boolean finalApprovalComplete){}public record Assessment(Decision decision,List<String>blockers,List<String>actions){}public enum Decision{POST,REVIEW,BLOCKED}}
